<?php require __DIR__.'/partials.php';
$where=[];$args=[];
foreach(['category','subcategory','device','brand'] as $key) if (!empty($_GET[$key])) {$where[]="$key = ?";$args[]=$_GET[$key];}
if (!empty($_GET['q'])) {$where[]='(name LIKE ? OR reference_code LIKE ? OR compatibility LIKE ? OR brand LIKE ?)'; for($i=0;$i<4;$i++)$args[]='%'.$_GET['q'].'%';}
$sql='SELECT * FROM products'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY created_at DESC';$st=db()->prepare($sql);$st->execute($args);$products=$st->fetchAll(); header_html('Repuestos electrónicos'); ?>
<main class="wrap"><section class="hero"><h1>RECAMBIOS QUE DEVUELVEN LA VIDA A TU TECNOLOGÍA</h1><p>Móviles, consolas, portátiles y accesorios. Consulta disponibilidad y realiza tu pedido por WhatsApp.</p></section><div class="layout"><section><p class="muted"><?=count($products)?> producto(s) encontrado(s)</p><div class="products"><?php foreach($products as $p): ?><article class="card"><div class="image"><?php if($p['image_path']): ?><img src="<?=e($p['image_path'])?>" alt="<?=e($p['name'])?>"><?php else: ?><?=e($p['icon'] ?: '📦')?><?php endif ?></div><h2><?=e($p['name'])?></h2><div class="muted"><?=e($p['brand'])?> · <?=e($p['compatibility'])?></div><div class="muted">Ref. <?=e($p['reference_code'])?></div><div class="stock">● <?= $p['stock']>0 ? 'En stock: '.(int)$p['stock'].' uds.' : 'Consultar disponibilidad' ?></div><div class="price"><?=number_format((float)$p['price'],2,',','.')?> €</div><button class="buy" data-id="<?=$p['id']?>" data-name="<?=e($p['name'])?>" data-ref="<?=e($p['reference_code'])?>" data-price="<?=$p['price']?>" data-stock="<?=$p['stock']?>">Añadir al carrito</button></article><?php endforeach ?><?php if(!$products): ?><p>No encontramos productos con ese filtro.</p><?php endif ?></div></section><aside class="panel cart"><h2>🛒 Tu carrito</h2><div id="cart"><p class="empty">Tu carrito está vacío.</p></div><div class="total"><span>Total</span><span id="total">0,00 €</span></div><button id="sendOrder" class="whatsapp" disabled>💬 Pedir por WhatsApp</button></aside></div></main>
<script>const wa='<?=WHATSAPP_NUMBER?>',cart=new Map();document.querySelectorAll('.buy').forEach(b=>b.onclick=()=>{let p={id:b.dataset.id,name:b.dataset.name,ref:b.dataset.ref,price:+b.dataset.price,stock:+b.dataset.stock},n=cart.get(p.id)?.n||0;if(n<p.stock)cart.set(p.id,{...p,n:n+1});draw()});function change(id,n){let p=cart.get(id);if(!p)return;p.n+=n;p.n>0?cart.set(id,p):cart.delete(id);draw()}function draw(){let total=0,rows='';cart.forEach(p=>{total+=p.price*p.n;rows+=`<div class="cartrow"><b>${p.name}</b><br><span>${p.price.toFixed(2).replace('.',',')} € × ${p.n}</span><div class="qty"><button onclick="change('${p.id}',-1)">−</button><span>${p.n}</span><button onclick="change('${p.id}',1)">+</button><button class="remove" onclick="change('${p.id}',-${p.n})">Eliminar</button></div></div>`});document.querySelector('#cart').innerHTML=rows||'<p class="empty">Tu carrito está vacío.</p>';document.querySelector('#total').textContent=total.toFixed(2).replace('.',',')+' €';document.querySelector('#sendOrder').disabled=!cart.size}document.querySelector('#sendOrder').onclick=()=>{let lines=['Hola Microtech, quiero realizar este pedido:',''];let total=0;cart.forEach(p=>{lines.push(`• ${p.name} | Ref. ${p.ref} | Cantidad: ${p.n}`);total+=p.price*p.n});lines.push('',`Total orientativo: ${total.toFixed(2).replace('.',',')} €`,'','Quedo pendiente de confirmar disponibilidad, envío y forma de pago.');window.open('https://wa.me/'+wa+'?text='+encodeURIComponent(lines.join('\n')),'_blank')}</script><?php footer_html(); ?>
